  1→/**
  2→ * Search Index Service
  3→ *
  4→ * Manages a client-side search index for file and folder names using MiniSearch.
  5→ * The index is encrypted with AES-256-GCM (key derived via HKDF from the user's
  6→ * vault private key) before persisting to IndexedDB for zero-knowledge on-disk storage.
  7→ *
  8→ * This is a pure TypeScript service with no React dependencies.
  9→ */
 10→
 11→import MiniSearch from 'minisearch';
 12→import type { FolderNode } from '../stores/folder.store';
 13→
 14→// ---------------------------------------------------------------------------
 15→// Types
 16→// ---------------------------------------------------------------------------
 17→
 18→/** A document stored in the MiniSearch index. */
 19→type SearchDocument = {
 20→  /** Unique key: `${folderId}:${childId}` (avoids collisions across folders) */
 21→  id: string;
 22→  /** File or folder name (what users search for) */
 23→  name: string;
 24→  /** Whether this is a file or folder */
 25→  type: 'file' | 'folder';
 26→  /** Breadcrumb path like "My Vault / Documents / Reports" */
 27→  parentPath: string;
 28→  /** Folder ID for navigation on result click */
 29→  parentFolderId: string;
 30→  /** Timestamp for display in results (Unix ms) */
 31→  modifiedAt: number;
 32→};
 33→
 34→/** A search result returned by the service. */
 35→export type SearchResult = {
 36→  id: string;
 37→  name: string;
 38→  type: 'file' | 'folder';
 39→  parentPath: string;
 40→  parentFolderId: string;
 41→  modifiedAt: number;
 42→  /** MiniSearch relevance score (higher = better match) */
 43→  score: number;
 44→  /** Match info from MiniSearch, maps field name to matching terms */
 45→  match: Record<string, string[]>;
 46→};
 47→
 48→// ---------------------------------------------------------------------------
 49→// MiniSearch options (shared between constructor and loadJSON)
 50→// ---------------------------------------------------------------------------
 51→
 52→const MINISEARCH_OPTIONS = {
 53→  fields: ['name'],
 54→  storeFields: ['name', 'type', 'parentPath', 'parentFolderId', 'modifiedAt'],
 55→  searchOptions: {
 56→    fuzzy: 0.2,
 57→    prefix: true,
 58→    boost: { name: 1 },
 59→  },
 60→};
 61→
 62→// ---------------------------------------------------------------------------
 63→// IndexedDB constants
 64→// ---------------------------------------------------------------------------
 65→
 66→const IDB_NAME = 'cipherbox-search';
 67→const IDB_VERSION = 1;
 68→const IDB_STORE = 'index';
 69→const IDB_KEY = 'encrypted-index';
 70→
 71→// ---------------------------------------------------------------------------
 72→// HKDF constants
 73→// ---------------------------------------------------------------------------
 74→
 75→const HKDF_INFO = 'cipherbox-search-index-v1';
 76→
 77→// ---------------------------------------------------------------------------
 78→// IndexedDB helpers (follows pattern from device/identity.ts)
 79→// ---------------------------------------------------------------------------
 80→
 81→function openSearchDB(): Promise<IDBDatabase> {
 82→  return new Promise((resolve, reject) => {
 83→    const request = indexedDB.open(IDB_NAME, IDB_VERSION);
 84→    request.onupgradeneeded = () => {
 85→      request.result.createObjectStore(IDB_STORE);
 86→    };
 87→    request.onsuccess = () => resolve(request.result);
 88→    request.onerror = () => reject(request.error);
 89→  });
 90→}
 91→
 92→// ---------------------------------------------------------------------------
 93→// SearchIndexService
 94→// ---------------------------------------------------------------------------
 95→
 96→export class SearchIndexService {
 97→  private miniSearch: MiniSearch<SearchDocument>;
 98→  private indexVersion: number = 0;
 99→
100→  constructor() {
101→    this.miniSearch = new MiniSearch<SearchDocument>(MINISEARCH_OPTIONS);
102→  }
103→
104→  /**
105→   * Build the full index from the folder store's folder tree.
106→   * Walks all loaded FolderNodes and indexes their children (files and folders).
107→   *
108→   * @param folders - Record<string, FolderNode> from folder store
109→   */
110→  buildFromFolderTree(folders: Record<string, FolderNode>): void {
111→    this.miniSearch.removeAll();
112→
113→    const documents: SearchDocument[] = [];
114→
115→    for (const folder of Object.values(folders)) {
116→      const parentPath = this.buildPath(folder.id, folders);
117→
118→      // Index each child (files and subfolders)
119→      for (const child of folder.children) {
120→        documents.push({
121→          id: `${folder.id}:${child.id}`,
122→          name: child.name,
123→          type: child.type === 'folder' ? 'folder' : 'file',
124→          parentPath,
125→          parentFolderId: folder.id,
126→          modifiedAt: child.modifiedAt ?? child.createdAt ?? 0,
127→        });
128→      }
129→    }
130→
131→    // Also index folders themselves (except root) as searchable items.
132→    // A folder's parent is its parentId, so it appears in search under
133→    // the parent folder's path.
134→    for (const folder of Object.values(folders)) {
135→      if (!folder.parentId) continue; // skip root
136→      const parentFolder = folders[folder.parentId];
137→      if (!parentFolder) continue;
138→
139→      const parentPath = this.buildPath(folder.parentId, folders);
140→
141→      // Use the folder's own id with a "self:" prefix to avoid collision
142→      // with the same folder appearing as a child entry
143→      documents.push({
144→        id: `${folder.parentId}:${folder.id}`,
145→        name: folder.name,
146→        type: 'folder',
147→        parentPath,
148→        parentFolderId: folder.parentId,
149→        modifiedAt: 0, // folders don't have a top-level modifiedAt
150→      });
151→    }
152→
153→    // Deduplicate: children already include subfolder entries from parent.
154→    // The folder-self entries above may overlap with child entries.
155→    // Use a Map to keep only one document per id.
156→    const deduped = new Map<string, SearchDocument>();
157→    for (const doc of documents) {
158→      if (!deduped.has(doc.id)) {
159→        deduped.set(doc.id, doc);
160→      }
161→    }
162→
163→    this.miniSearch.addAll(Array.from(deduped.values()));
164→    this.indexVersion++;
165→  }
166→
167→  /**
168→   * Search the index with fuzzy matching.
169→   *
170→   * @param query - user's search string
171→   * @returns Array of SearchResult sorted by relevance score (descending)
172→   */
173→  search(query: string): SearchResult[] {
174→    if (!query.trim()) return [];
175→
176→    const results = this.miniSearch.search(query);
177→
178→    return results.map((result) => ({
179→      id: result.id as string,
180→      name: result.name as string,
181→      type: result.type as 'file' | 'folder',
182→      parentPath: result.parentPath as string,
183→      parentFolderId: result.parentFolderId as string,
184→      modifiedAt: result.modifiedAt as number,
185→      score: result.score,
186→      match: result.match,
187→    }));
188→  }
189→
190→  /**
191→   * Persist the current index to IndexedDB, encrypted with a key derived
192→   * from the user's vault private key via HKDF.
193→   *
194→   * @param userPrivateKey - user's secp256k1 private key (32 bytes) for HKDF derivation
195→   */
196→  async persistEncrypted(userPrivateKey: Uint8Array): Promise<void> {
197→    try {
198→      const searchKey = await this.deriveSearchKey(userPrivateKey);
199→      const serialized = JSON.stringify(this.miniSearch.toJSON());
200→      const plaintext = new TextEncoder().encode(serialized);
201→
202→      const iv = crypto.getRandomValues(new Uint8Array(12));
203→      const ciphertext = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, searchKey, plaintext);
204→
205→      const db = await openSearchDB();
206→      const tx = db.transaction(IDB_STORE, 'readwrite');
207→      const store = tx.objectStore(IDB_STORE);
208→
209→      // Store as number[] for cross-browser IndexedDB compatibility
210→      store.put(
211→        {
212→          iv: Array.from(iv),
213→          data: Array.from(new Uint8Array(ciphertext)),
214→        },
215→        IDB_KEY
216→      );
217→
218→      await new Promise<void>((resolve, reject) => {
219→        tx.oncomplete = () => resolve();
220→        tx.onerror = () => reject(tx.error);
221→      });
222→    } catch (err) {
223→      console.warn('[SearchIndex] Failed to persist encrypted index:', err);
224→    }
225→  }
226→
227→  /**
228→   * Load the index from IndexedDB and decrypt.
229→   *
230→   * @param userPrivateKey - user's secp256k1 private key (32 bytes) for HKDF derivation
231→   * @returns true if index was loaded successfully, false if not found or decryption failed
232→   */
233→  async loadEncrypted(userPrivateKey: Uint8Array): Promise<boolean> {
234→    try {
235→      const db = await openSearchDB();
236→      const tx = db.transaction(IDB_STORE, 'readonly');
237→      const store = tx.objectStore(IDB_STORE);
238→
239→      const stored = await new Promise<{
240→        iv: number[];
241→        data: number[];
242→      } | null>((resolve, reject) => {
243→        const request = store.get(IDB_KEY);
244→        request.onsuccess = () => resolve(request.result ?? null);
245→        request.onerror = () => reject(request.error);
246→      });
247→
248→      if (!stored || !stored.iv || !stored.data) return false;
249→
250→      const searchKey = await this.deriveSearchKey(userPrivateKey);
251→      const iv = new Uint8Array(stored.iv);
252→      const ciphertext = new Uint8Array(stored.data);
253→
254→      const plaintext = await crypto.subtle.decrypt({ name: 'AES-GCM', iv }, searchKey, ciphertext);
255→
256→      const serialized = new TextDecoder().decode(plaintext);
257→      const json = JSON.parse(serialized);
258→
259→      this.miniSearch = MiniSearch.loadJSON(JSON.stringify(json), MINISEARCH_OPTIONS);
260→      return true;
261→    } catch (err) {
262→      console.warn('[SearchIndex] Failed to load encrypted index:', err);
263→      return false;
264→    }
265→  }
266→
267→  /**
268→   * Clear the in-memory index and remove the encrypted entry from IndexedDB.
269→   * Call on logout.
270→   */
271→  async clear(): Promise<void> {
272→    this.miniSearch.removeAll();
273→
274→    try {
