/**
 * Shared browser styles -- "Shared with me" view
 *
 * Extends file-browser.css with shared-specific elements:
 * - [RO] badge for read-only indicators
 * - SHARED BY column for truncated pubkeys
 * - Error state styling
 */

/* Read-only badge */
.shared-ro-badge {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  color: var(--color-text-dim);
  margin-left: var(--spacing-xs);
  opacity: 0.7;
  user-select: none;
}

/* Shared by column */
.shared-by-cell {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  color: var(--color-green-primary);
  opacity: 0.8;
  min-width: 120px;
  max-width: 160px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Header for shared by column */
.file-list-header-shared-by {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  color: var(--color-text-dim);
  opacity: 0.6;
  min-width: 120px;
  max-width: 160px;
  padding: 0 var(--spacing-sm);
}

/* Shared list row */
.shared-list-row {
  cursor: pointer;
}

.shared-list-row:hover {
  background: rgb(0 255 128 / 5%);
}

.shared-list-row:focus-visible {
  outline: 1px solid var(--color-green-primary);
  outline-offset: -1px;
}

/* ==========================================================================
   File List Row -- grid layout for .file-list-row / .file-list-cell-* classes
   used by SharedListRow and SharedFolderRow components.
   Scoped under .shared-browser to avoid leaking to the main file browser.
   ========================================================================== */

/* Row base */
.shared-browser .file-list-row {
  display: grid;
  grid-template-columns: 1fr 120px 180px;
  gap: var(--spacing-md);
  padding: var(--spacing-sm) var(--spacing-md);
  cursor: pointer;
  transition: background-color 0.15s ease;
  border-bottom: var(--border-thickness) solid var(--color-border-dim);
  font-family: var(--font-family-mono);
}

.shared-browser .file-list-row:last-child {
  border-bottom: none;
}

.shared-browser .file-list-row:hover {
  background-color: var(--color-green-darker);
}

.shared-browser .file-list-row:focus-visible {
  outline: 1px solid var(--color-green-primary);
  outline-offset: -1px;
}

/* Parent directory row [..] PARENT_DIR */
.shared-browser .file-list-row--parent {
  cursor: pointer;
}

.shared-browser .file-list-row--parent:hover {
  background-color: var(--color-green-darker);
}

/* Cell base */
.shared-browser .file-list-cell {
  display: flex;
  align-items: center;
  min-width: 0;
}

/* Name column */
.shared-browser .file-list-cell-name {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

/* Size column */
.shared-browser .file-list-cell-size {
  display: flex;
  align-items: center;
  color: var(--color-text-secondary);
  font-size: var(--font-size-sm);
}

/* Date column */
.shared-browser .file-list-cell-date {
  display: flex;
  align-items: center;
  color: var(--color-text-secondary);
  font-size: var(--font-size-sm);
}

/* File/folder icon */
.shared-browser .file-icon {
  font-size: var(--font-size-sm);
  flex-shrink: 0;
}

/* File/folder name text */
.shared-browser .file-name {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--color-text-primary);
  font-size: var(--font-size-sm);
}

/* Error state */
.shared-error {
  font-family: var(--font-mono);
  font-size: 0.85rem;
  color: var(--color-red, #ef4444);
  padding: var(--spacing-md) var(--spacing-lg);
  text-align: center;
  opacity: 0.9;
}

/* Shared browser container overrides */
.shared-browser .file-browser-toolbar {
  border-bottom: 1px solid rgb(0 255 128 / 10%);
}

